            var cm = android.webkit.CookieManager.getInstance();
            cm.flush();
            var ck = cm.getCookie("https://18comic.vip");
            if (ck) {
                cookie.setCookie("https://18comic.vip", ck);
            }
        } catch(ce) {}

        // 直接返回已过盾的浏览器渲染页面，严禁再次调用 connect(url) 导致 403 死循环
        if (browserRes && browserRes.body() && browserRes.body().length > 200 && browserRes.body().indexOf("Just a moment...") === -1) {
            return browserRes;
        }

        return result;
    } catch(e) {
