if (baseUrl.indexOf("novel") !== -1) {
    result;
} else {
    var lines = String(result).split("\n");
    var newLines = [];
    var seen = {};
    for (var i = 0; i < lines.length; i++) {
        var line = lines[i].trim();
        if (!line || seen[line]) continue;

        // 核心过滤：必须包含 /media/photos/ 才是真实漫画切片，彻底消除广告与误匹配
        var isComic = line.indexOf("/media/photos/") !== -1 || line.match(/\/photos\/\d+\/\d+/i);
        var isAd = line.match(/(logo|icon|avatar|banner|ad_|ads\/|pop|sponsor|traffic|game|bet|advertisement)/i);

        if (isComic && !isAd) {
            seen[line] = true;
            if (line.indexOf("<img") === 0) {
                newLines.push(line);
            } else {
                newLines.push('<img src="' + line + '">');
            }
        }
    }
    // 兜底：如果过滤过严，保留包含 photos 的有效图片
    if (newLines.length === 0) {
        for (var j = 0; j < lines.length; j++) {
            var l = lines[j].trim();
            if (l && l.indexOf("http") !== -1 && !seen[l]) {
                if (l.indexOf("photos") !== -1 && !l.match(/(logo|icon|avatar|banner|ad|advertisement)/i)) {
                    seen[l] = true;
                    newLines.push('<img src="' + l + '">');
                }
            }
        }
    }
    newLines.join("\n");
}

